(()=>{const e=document.querySelector(".hero"),n=document.querySelector(".hero--actions"),o=document.querySelector(".hero--title"),r=document.querySelector(".hero--intro"),t=n.getBoundingClientRect();return JSON.stringify({viewport:innerWidth+"x"+innerHeight,heroHoogte:Math.round(e.getBoundingClientRect().height),h1:Math.round(o.getBoundingClientRect().height),intro:Math.round(r.getBoundingClientRect().height),knoppenOnderkant:Math.round(t.bottom),buitenBeeld:Math.round(t.bottom-innerHeight),zichtbaar:t.bottom<=innerHeight+1})})();
